#include <stdio.h>
#include <ctype.h>
int main(void) {
    char text[4096];
    if (!fgets(text, sizeof(text), stdin)) return 0;
    int count = 0;
    for (int i = 0; text[i] != '\0'; i++) {
        char ch = (char)tolower((unsigned char)text[i]);
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') count++;
    }
    printf("%d\n", count);
    return 0;
}

