using namespace std;
int main() {
    string text; getline(cin, text);
    int count = 0;
    for (unsigned char ch : text) {
        char c = (char)tolower(ch);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') count++;
    }
    cout << count << endl;
